<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { useBookingStore } from '@/stores/booking'
import { useAuthStore } from '@/stores/auth'
const store = useBookingStore(); const auth = useAuthStore(); const router = useRouter(); const date = ref(new Date().toISOString().slice(0, 10)); const selected = ref(1); const loading = ref(false); const error = ref('')
const total = computed(() => store.selectedSlots.reduce((sum, slot) => sum + slot.price, 0)); const money = (value: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value); const image = (index: number) => store.courts[index]?.image_url || `/aura/court-${index + 4}.jpg`
onMounted(async () => { await store.loadCourts(); if (store.courts[0]) { selected.value = store.courts[0].id; await store.loadAvailability(selected.value, date.value) } })
async function chooseCourt(id: number) { selected.value = id; await store.loadAvailability(id, date.value) }
async function submit() { if (!auth.user) return router.push({ name: 'login', query: { redirect: '/booking' } }); if (!store.selectedSlots.length) return; loading.value = true; error.value = ''; try { await store.createBooking(); router.push('/payment') } catch (e: any) { error.value = e.message || 'Không thể tạo booking.' } finally { loading.value = false } }
function scrollToAvailability() { document.getElementById('availability')?.scrollIntoView({ behavior: 'smooth' }) }
</script>
<template>
  <section class="hero"><div><div class="eyebrow">Premium Athletics</div><h1>Where Precision <em>Meets Performance.</em></h1><p>Trải nghiệm nhịp điệu của trận đấu trên những sân cầu lông chuyên nghiệp. Đặt sân trong vài giây và bắt đầu cuộc chơi.</p><div class="actions"><RouterLink to="/courts" class="btn">Book a Court <span class="material-symbols-outlined">arrow_forward</span></RouterLink><a href="#features" class="btn secondary">Explore Aura</a></div></div><div class="hero-mosaic"><div><img class="short" src="/aura/court-1.jpg" alt="Sân cầu lông Aura Court" /><img class="tall" src="/aura/court-2.jpg" alt="Sàn sân cầu lông" style="margin-top:12px" /></div><div><img class="tall" src="/aura/court-3.jpg" alt="Vận động viên cầu lông" /><div class="access-card" style="margin-top:12px"><div><strong>24/7</strong><span>ACCESS</span></div></div></div></div></section>
  <section class="search-strip"><div class="search-field"><label>Location</label><input value="Aura Court Club" readonly /></div><div class="search-field"><label>Date</label><input v-model="date" type="date" @change="store.loadAvailability(selected, date)" /></div><div class="search-field"><label>Time Slot</label><select><option>All available slots</option><option>Morning · 06:00–12:00</option><option>Evening · 17:00–23:00</option></select></div><button class="search-action" @click="scrollToAvailability">search</button></section>
  <section class="section" id="availability"><div class="section-head"><div><div class="eyebrow">Explore Facilities</div><h2>Featured Arenas</h2></div><RouterLink to="/courts" class="muted">View all courts <span class="material-symbols-outlined">arrow_forward</span></RouterLink></div><div class="court-grid"><RouterLink v-for="(court, index) in store.courts" :key="court.id" :to="`/courts/${court.id}`" class="court-card"><div class="court-card-image"><img :src="image(index)" :alt="court.name" /><span class="tag">From {{ money((court.price_slots?.[0]?.price || 120000)) }}/hr</span></div><div class="court-info"><h3>{{ court.name }}</h3><p class="muted"><span class="material-symbols-outlined">location_on</span> {{ court.description || 'Aura Court Club' }}</p></div></RouterLink></div></section>
  <section class="section" style="padding-top:10px" id="features"><div class="section-head"><div><div class="eyebrow">The Aura Standard</div><h2>Everything in flow.</h2></div></div><div class="feature-row"><article class="feature"><span class="feature-icon">bolt</span><h3>Book in seconds</h3><p class="muted">Lịch sân rõ ràng, chọn slot nhanh và giữ chỗ tức thì.</p></article><article class="feature"><span class="feature-icon">verified</span><h3>Premium courts</h3><p class="muted">Mặt sân, ánh sáng và không gian được chăm chút.</p></article><article class="feature"><span class="feature-icon">payments</span><h3>Secure checkout</h3><p class="muted">Thanh toán QR an toàn, trạng thái cập nhật theo thời gian thực.</p></article></div></section>
  <div v-if="store.selectedSlots.length" class="floating-booking"><span>{{ store.selectedSlots.length }} slot · {{ money(total) }}</span><button class="btn pink" :disabled="loading" @click="submit">Continue</button></div><p v-if="error" class="error container">{{ error }}</p>
</template>
